use crate::aap::caps::kb_read;
use crate::aap::caps::tool_llm::{self, Reply};
use crate::aap::caps::types::{AgentResponse, Intent, LlmError};

struct Node;

fn intent_label(intent: Intent) -> &'static str {
    match intent {
        Intent::BillingQuestion => "billing-question",
        Intent::TechnicalSupport => "technical-support",
        Intent::AccountChange => "account-change",
        Intent::GeneralInquiry => "general-inquiry",
        Intent::Unknown => "unknown",
    }
}

impl Guest for Node {
    fn run(ctx: ConversationContext) -> ResponseResult {
        let system = format!(
            "You are a customer-support agent. The classified intent is '{}'. \
             Answer the question using only the knowledge provided. If you need \
             more information, ask to invoke the 'lookup' tool with a search query.",
            intent_label(ctx.intent)
        );

        let mut prompt = String::new();
        prompt.push_str("Question: ");
        prompt.push_str(&ctx.question);
        if !ctx.knowledge.is_empty() {
            prompt.push_str("\n\nKnowledge:\n");
            for k in &ctx.knowledge {
                prompt.push_str("- ");
                prompt.push_str(k);
                prompt.push('\n');
            }
        }

        // Bounded tool-orchestration loop: the model either answers, or asks for
        // a tool. The only tool this node holds authority for is kb-read's lookup;
        // any other request is refused as a value, never invoked.
        const MAX_ROUNDS: u32 = 4;
        for _ in 0..MAX_ROUNDS {
            match tool_llm::generate(&system, &prompt) {
                Reply::Text(text) => {
                    return ResponseResult::Ok(AgentResponse { text });
                }
                Reply::Call(req) => {
                    if req.tool == "lookup" {
                        let results = kb_read::lookup(&req.query);
                        prompt.push_str("\n\nTool 'lookup' results for \"");
                        prompt.push_str(&req.query);
                        prompt.push_str("\":\n");
                        if results.is_empty() {
                            prompt.push_str("(no results)\n");
                        } else {
                            for r in &results {
                                prompt.push_str("- ");
                                prompt.push_str(r);
                                prompt.push('\n');
                            }
                        }
                    } else {
                        return ResponseResult::Error(LlmError {
                            message: format!(
                                "model requested unavailable tool '{}'",
                                req.tool
                            ),
                        });
                    }
                }
            }
        }

        ResponseResult::Error(LlmError {
            message: "tool-orchestration loop did not converge on a response".to_string(),
        })
    }
}

export!(Node);
